	@TestFactory
	public Stream<DynamicTest> freshPathVariablesWorkWithArrayBindingLayouts() {
		String predicate = "<" + RDFS.SUBCLASSOF + ">";
		return List.of("?s " + predicate + "+ <" + three + ">", "<" + one + "> " + predicate + "+ ?o",
				"<" + one + "> " + predicate + "+ <" + three + ">", "<" + three + "> ^" + predicate + "+ ?s",
				"?s (" + predicate + "/" + predicate + ")+ <" + three + ">")
				.stream()
				.map(pattern -> DynamicTest.dynamicTest(pattern, () -> {
					QueryRoot generic = new QueryRoot(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
							"SELECT * WHERE { " + pattern + " }", null).getTupleExpr());
					QueryRoot array = generic.clone();
					List<BindingSet> expected;
					try (var rows = evaluator.precompile(generic, new QueryEvaluationContext.Minimal(null))
							.evaluate(EmptyBindingSet.getInstance())) {
						expected = QueryResults.asList(rows);
					}
					assertThat(expected).isNotEmpty();
					QueryEvaluationContext context = new ArrayBindingBasedQueryEvaluationContext(
							new QueryEvaluationContext.Minimal(null),
							ArrayBindingBasedQueryEvaluationContext.findAllVariablesUsedInQuery(array), null);
					try (var rows = evaluator.precompile(array, context).evaluate(EmptyBindingSet.getInstance())) {
						assertThat(QueryResults.asList(rows)).containsExactlyInAnyOrderElementsOf(expected);
					}
				}));
	}

	@Test
	public void privatePathLayoutSharesAllQueryState() {
		Literal now = vf.createLiteral("shared now");
		BNode bnode = vf.createBNode();
		SimpleDataset dataset = new SimpleDataset();
		Comparator<Value> comparator = Comparator.comparing(Value::stringValue);
		AtomicInteger captures = new AtomicInteger();
		QueryEvaluationContext state = new QueryEvaluationContext.Minimal(now, dataset, comparator) {
			@Override
			public BNode getOrCreateBNode(String label, BindingSet bindings, ValueFactory factory) {
				return bnode;
			}

			@Override
			public Value captureConstant(Value value, Function<Value, Value> capturer) {
				captures.incrementAndGet();
				return capturer.apply(value);
			}
		};
		QueryEvaluationContext.ActiveGraph active = new QueryEvaluationContext.ActiveGraph(one, one);
		QueryEvaluationContext parent = new ActiveGraphQueryEvaluationContext(
				new ArrayBindingBasedQueryEvaluationContext(state, new String[] { "subClass", "superClass" },
						comparator),
				active);
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		when(strategy.getCollectionFactory()).thenReturn(evaluator.getCollectionFactory());
		when(strategy.precompile(any(TupleExpr.class), any(QueryEvaluationContext.class))).thenAnswer(call -> {
			QueryEvaluationContext child = call.getArgument(1);
			assertThat(child.getNow()).isSameAs(now);
			assertThat(child.getDataset()).isSameAs(dataset);
			assertThat(child.getActiveGraph()).isSameAs(active);
			assertThat(child.getComparator()).isSameAs(comparator);
			assertThat(child.getOrCreateBNode("label", EmptyBindingSet.getInstance(), vf)).isSameAs(bnode);
			assertThat(child.captureConstant(one, ignored -> two)).isSameAs(two);
			assertThat(captures).hasValue(1);
			MutableBindingSet row = child.createBindingSet();
			child.addBinding("freshScratchName").accept(one, row);
			assertThat(child.getValue("freshScratchName").apply(row)).isSameAs(one);
			return (QueryEvaluationStep) ignored -> QueryEvaluationStep.EMPTY_ITERATION;
		});
		try (PathIteration path = new PathIteration(strategy, Scope.DEFAULT_CONTEXTS, Var.of("subClass"),
				new SingletonSet(), Var.of("superClass"), null, 1, EmptyBindingSet.getInstance(), parent)) {
			assertThat(path.hasNext()).isFalse();
		}
	}

